const main=document.querySelector('main');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function svgArt(kind,color='orange',hero=false){const stroke={orange:'#bd583a',green:'#6b7b5c',purple:'#88739a',blue:'#648092'}[color]||'#bd583a';let content='';const box=(x,y,w,h,label,sub='')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="4" fill="#fffdf6" stroke="${stroke}" stroke-width="1.3"/><text x="${x+w/2}" y="${y+25}" text-anchor="middle" font-size="11" fill="#333a32">${label}</text>${sub?`<text x="${x+w/2}" y="${y+42}" text-anchor="middle" font-size="8" fill="#79816f">${sub}</text>`:''}`;
if(kind==='infra'){content=box(145,8,110,48,'GITHUB ACTIONS')+`<path d="M200 56V78M95 78H305M95 78V102M305 78V102" stroke="${stroke}" fill="none"/>`+box(35,102,120,63,'STAGING','필요 시 기동 / 중지')+box(245,102,120,63,'PRODUCTION','ALB · EC2 · RDS')+`<path d="M155 135H245" stroke="${stroke}" stroke-dasharray="4 5"/><text x="200" y="128" font-size="8" text-anchor="middle" fill="#79816f">DB SYNC</text><circle cx="95" cy="85" r="3" fill="${stroke}"/><circle cx="305" cy="85" r="3" fill="${stroke}"/>`}
else if(kind==='vision'){content=`<rect x="30" y="15" width="340" height="165" rx="4" fill="none" stroke="${stroke}" opacity=".4"/><path d="M30 125L370 80M95 15L160 180M295 15L245 180" stroke="${stroke}" opacity=".15"/>`;[[65,85,32,55],[115,45,25,42],[180,65,29,48],[250,35,22,38],[300,105,35,60],[218,120,32,52]].forEach(([x,y,w,h],i)=>{content+=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${stroke}" fill-opacity=".05" stroke="${stroke}"/><circle cx="${x+w/2}" cy="${y+10}" r="3" fill="${stroke}"/><text x="${x}" y="${y-5}" fill="${stroke}" font-size="7">PERSON / 0${i+1}</text>`});content+=`<rect x="40" y="150" width="107" height="21" fill="#fffdf6"/><text x="49" y="164" font-size="8" fill="${stroke}">RTSP → MODEL → API</text>`}
else {content=box(20,62,92,64,'INPUT','DOCUMENT / DATA')+box(153,62,94,64,'PROCESS','MODEL · PIPELINE')+box(288,62,92,64,'OUTPUT','API / REPORT');content+=`<path d="M112 94H153M247 94H288" stroke="${stroke}"/><path d="M142 89l8 5-8 5M277 89l8 5-8 5" stroke="${stroke}" fill="none"/><text x="200" y="155" font-size="8" text-anchor="middle" fill="#79816f">분석 결과를 사용 가능한 흐름으로</text>`}
return `<svg viewBox="0 0 400 195" role="img" aria-label="${kind==='infra'?'staging과 production 분리 구조':kind==='vision'?'CCTV 분석 결과를 설명하는 재구성 도식':'입력, 처리, 출력의 연결 구조'}" xmlns="http://www.w3.org/2000/svg"><defs><pattern id="dots-${kind}-${color}-${hero}" width="14" height="14" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="${stroke}" opacity=".14"/></pattern></defs><rect width="400" height="195" fill="url(#dots-${kind}-${color}-${hero})"/>${content}</svg>`}
function card(p,featured=false){return `<a class="card ${featured?'featured':''}" href="#project/${p.id}" aria-label="${esc(p.title)} 자세히 보기"><div class="card-art ${p.color}"><span><span>CASE STUDY / ${p.n}</span><span>↗</span></span>${svgArt(p.diagram,p.color)}</div><div class="card-copy"><div class="tag">${p.tag}</div><h3>${p.title}</h3><p>${p.desc}</p><div class="card-foot"><span>${p.status.split(' · ').slice(0,2).join(' · ')}</span><b aria-hidden="true">↗</b></div></div></a>`}
function home(){return `<section class="hero"><div><div class="eyebrow">BACKEND · AI INTEGRATION · OPERATIONS</div><h1>문제를 읽고,<br>동작하는 <em>흐름</em>으로.</h1><p>안녕하세요, 윤준명입니다.<br>영상 분석 결과를 서비스로 연결하고,<br>운영 중 드러나는 문제를 설계와 개선으로 풀어왔습니다.</p><div class="actions"><a class="btn dark" href="#portfolio">프로젝트 살펴보기 <span>↗</span></a><a class="textlink" href="#resume">이력서 보기 →</a></div></div><div class="hero-board"><div class="board-caption"><span>FROM REQUIREMENTS TO OPERATIONS</span><span>FIG. 01</span></div>${svgArt('infra','green',true)}<div class="board-bottom"><span>DESIGN → BUILD → OPERATE</span><span>구조로 설명하는 경험</span></div></div></section><div class="ribbon"><div><b>01 /</b><span><strong>문제를 구체화</strong><small>업무 규칙과 시스템 흐름 설계</small></span></div><div><b>02 /</b><span><strong>데이터를 연결</strong><small>AI 분석 결과와 서비스 API 연계</small></span></div><div><b>03 /</b><span><strong>운영에서 개선</strong><small>병목 추적과 배포 구조 변경</small></span></div></div><section class="section"><div class="section-head"><div><div class="eyebrow">SELECTED WORK</div><h2>문제에서 출발한 프로젝트</h2><p>무엇을 만들었는지, 어떤 판단을 했는지.<br>실제 역할과 해결 과정을 중심으로 정리했습니다.</p></div><a class="textlink" href="#portfolio">전체 프로젝트 06 →</a></div><div class="grid">${card(PROJECTS[0],true)}${card(PROJECTS[1])}${card(PROJECTS[2])}</div></section><section class="about section"><div><div class="eyebrow">HOW I WORK</div><h2>선택의 이유와<br>역할을 분명하게.</h2></div><div class="principles"><div><h3>작게 나눠, 원인을 찾습니다.</h3><p>모듈을 개별 실행하고 코드를 추적하며 병목을 좁혔습니다. 결과뿐 아니라 문제를 찾은 과정도 설명합니다.</p></div><div><h3>AI와 본인의 역할을 구분합니다.</h3><p>AI를 개발 도구로 활용한 경험과 제품에 AI 기능을 연결한 경험을 구분하고, 직접 판단한 범위를 명시합니다.</p></div></div></section><div class="closing"><div><h2>경험을 한눈에.</h2><p>경력과 주요 성과, 사용 기술을 이력서에서 확인하세요.</p></div><a class="btn dark" href="#resume">이력서 읽기 <span>↗</span></a></div>`}
function portfolio(filter='all'){const items=PROJECTS.filter(p=>filter==='all'||p.type===filter);return `<section class="page-head"><div class="eyebrow">PROJECT INDEX / 06</div><h1>프로젝트</h1><p>회사에서 마주한 운영 문제부터 개인적인 설계 실험까지.<br>각 카드에서 역할·구조·개선 과정을 자세히 볼 수 있습니다.</p></section><div class="filters" aria-label="프로젝트 필터">${[['all','전체 06'],['company','업무·개별 수행 04'],['personal','개인 프로젝트 02']].map(([v,l])=>`<button class="filter" data-filter="${v}" aria-pressed="${filter===v}">${l}</button>`).join('')}</div><div class="grid" style="padding-bottom:70px">${items.map(p=>card(p)).join('')}</div>`}
function project(id){const p=PROJECTS.find(x=>x.id===id);if(!p)return `<div class="empty"><h1>프로젝트를 찾을 수 없습니다.</h1><a href="#portfolio">프로젝트 목록으로 →</a></div>`;let infra=p.id==='htm'?`<div class="infra-before-after"><div class="infra-box"><small>BEFORE / 공유 인프라</small><div class="node">staging + production</div><div class="node">EC2 · RDS 공유</div><p>배포·예약 작업·자원 부족의 운영 영향</p></div><div class="infra-box after"><small>AFTER / 환경 분리</small><div class="node">production / EC2 + RDS</div><div class="node">staging / EC2 + RDS</div><p>필요 시 기동·중지 / GitHub Actions</p></div></div>`:'';return `<a class="breadcrumb" href="#portfolio">← 프로젝트 목록</a><section class="project-top"><div class="eyebrow">CASE STUDY / ${p.n}</div><h1>${p.title}</h1><p class="subtitle">${p.sub}</p><div class="project-meta"><div><small>CONTEXT / STATUS</small><p>${p.status}</p></div><div><small>MY ROLE</small><p>${p.role}</p></div></div><div class="chips">${p.stack.map(s=>`<span>${s}</span>`).join('')}</div>${p.url?`<a class="btn" href="${p.url}" target="_blank" rel="noopener">공개 서비스 방문 ↗</a>`:''}</section><div class="project-layout"><aside class="toc"><div class="eyebrow">IN THIS CASE</div>${p.sections.map((s,i)=>`<a href="#section-${i}" data-scroll="section-${i}">${String(i+1).padStart(2,'0')} / ${s[0]}</a>`).join('')}</aside><article class="article"><p class="intro">${p.summary}</p><div class="flowbox"><div class="eyebrow">PROCESS OVERVIEW</div><div class="flow">${p.flow.map((s,i)=>`${i?'<span aria-hidden="true">→</span>':''}<div>${s}</div>`).join('')}</div>${infra}<p class="diagram-note">설명용으로 재구성한 도식입니다. 실제 운영 화면·설정값을 포함하지 않습니다.</p></div>${p.sections.map((s,i)=>`<section id="section-${i}"><div class="eyebrow">${String(i+1).padStart(2,'0')}</div><h2>${s[0]}</h2><ul>${s[1].map(t=>`<li>${t}</li>`).join('')}</ul></section>`).join('')}</article></div><div class="project-nav"><a href="#portfolio">← 모든 프로젝트</a><a href="#project/${PROJECTS[(PROJECTS.indexOf(p)+1)%PROJECTS.length].id}">다음 사례 보기 →</a></div>`}
function resume(){const h=PROJECTS[0],v=PROJECTS[1],d=PROJECTS[2],m=PROJECTS[3];return `<section class="page-head"><div class="eyebrow">RESUME</div><h1>윤준명 <span style="font-size:.4em;color:var(--muted)">/ Backend · AI Integration</span></h1><p>CCTV 분석 파이프라인, AI API와 실제 서비스 운영을 경험했습니다.<br>분석 결과를 서비스에 연결하고 성능·운영 문제를 개선합니다.</p><div class="print-label">GitHub: https://github.com/newbission</div><div class="actions"><button class="btn dark" id="print-resume">인쇄 / PDF 저장 <span>↓</span></button><a class="textlink" href="https://github.com/newbission" target="_blank" rel="noopener">GitHub ↗</a></div></section><div class="resume-layout"><aside class="resume-aside"><a href="#resume-career" data-scroll="resume-career">01 경력</a><a href="#resume-tech" data-scroll="resume-tech">02 기술·활용 범위</a><a href="#resume-education" data-scroll="resume-education">03 학력·자격</a></aside><div class="resume-main"><section id="resume-career"><h2>경력</h2><h3>위더스코퍼레이션</h3><p class="date">2026.02–현재 · 프리랜서 · 업무 시스템 설계·운영</p><h4>HTM · 근태·채용 시스템</h4><ul><li>요구사항·업무 규칙, 시스템 구조와 화면 흐름을 설계하고 AI를 활용해 구현·배포·운영을 진행했습니다.</li><li>채용 확정→조직 멤버 전환→매장 배정과 스케줄·태블릿 출퇴근 흐름을 구성했습니다.</li><li>운영 간섭에 대응해 staging·production의 EC2·RDS를 분리하고 GitHub Actions 기반 필요 시 staging 운영을 설계·적용했습니다.</li><li>S3·CloudFront 배포 버전 관리, ALB 기반 무중단 배포와 production 인스턴스 변경을 진행했습니다.</li></ul><a class="case-link" href="#project/htm">설계·운영 사례 자세히 →</a><h3>주식회사 애나</h3><p class="date">2025.06–2026.02 · 계약직 · AI·API 개발</p><h4>실시간 군중 분석·이상상황 탐지 연계</h4><ul><li>RTSP 군중 분석 결과를 H100의 모델별 프로세스에서 수집하고 Kafka·Redis와 연계해 프로그램 서버로 전달했습니다.</li><li>이상상황 데이터를 수집·보완하고 관련 모델 학습 및 선별 영상 기반 시연을 진행했습니다.</li></ul><h4>오토라벨링 성능 개선</h4><ul><li>군중 모델의 점 좌표·밀도 맵 기반 박스 후보와 YOLO 사람 여부 검증 흐름을 개선했습니다.</li><li>모듈별 실행·디버깅으로 병목을 추적하고 탐색 구조를 변경해, 다음 날까지 미완료되기도 하던 작업을 당시 테스트에서 1시간 이내에 완료했습니다.</li></ul><a class="case-link" href="#project/vision">처리 흐름과 성능 개선 사례 →</a><h4>문서·음성 AI 파이프라인 개선 및 API 서비스화</h4><ul><li>기존 AI 처리 코드를 인수해 모델 재로딩 구조·PDF 변환 속도·한글 인식 품질을 개선했습니다.</li><li>Node.js API와 Nginx·Certbot 기반 HTTPS 환경 구성·배포를 단독 담당했습니다.</li></ul><a class="case-link" href="#project/document-ai">API·파이프라인 사례 →</a><h4>망원시장 방문객 분석</h4><ul><li>방문객 통계 조회·비교를 위한 WinForms 뷰어와 HTML 보고서·ChatGPT API 분석 문구 생성 기능을 구성했습니다.</li></ul><a class="case-link" href="#project/mangwon">분석·보고서 사례 →</a><h3>넥스트러너스</h3><p class="date">2025.02–2025.06 · 프리랜서 강사 / 2024.08–2025.01 · 계약직 조교</p><ul><li>9기·11기 수강생 대상 Python 백엔드 보충 강의 진행</li><li>수업 보조, 학습 자료 보충과 질의응답 담당</li></ul></section><section id="resume-tech"><h2>기술·활용 범위</h2><div class="chips">${['Python','Node.js','YOLO','RTSP','Kafka','Redis','AWS','Nginx','GitHub Actions','WinForms','Django','FastAPI','Docker','Git'].map(s=>`<span>${s}</span>`).join('')}</div><p>Python·YOLO: 영상 분석·오토라벨링 / Kafka·Redis: 기존 서버 연계와 분석 결과 전달 / AWS: 인프라·배포·운영 / Node.js·Nginx·Certbot: AI API와 HTTPS 배포</p><h4>AI 개발 도구와 제품 기능</h4><p>HTM에서는 주요 설계·운영 판단을 담당하고 코드 구현에 Claude Code를 활용했습니다. 오토라벨링 당시에는 Claude 웹과 직접 디버깅을 병행했습니다. 제품 기능으로는 영상 분석 모델·문서·음성 AI API·ChatGPT API 보고서 연동을 경험했습니다.</p></section><section id="resume-education"><h2>학력·교육·자격</h2><h4>명지전문대학 컴퓨터공학과</h4><p>2020.03–2023.02 · 전문학사 졸업</p><h4>Python(Django) 백엔드 온라인 부트캠프</h4><p>2024.06 수료 · 프론트엔드·기획과 협업한 프로젝트 2회</p><ul><li>SQL 개발자(SQLD) · 2023.10</li><li>정보처리산업기사 · 2023.09</li></ul></section></div></div>`}
function render(){const hash=location.hash.slice(1)||'home';if(hash.startsWith('section-')||hash.startsWith('resume-'))return;const [view,id]=hash.split('/');main.innerHTML=view==='portfolio'?portfolio():view==='project'?project(id):view==='resume'?resume():home();document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(view==='project'?'portfolio':view);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=(view==='resume'?'이력서':view==='portfolio'?'프로젝트':view==='project'?(PROJECTS.find(p=>p.id===id)?.title||'프로젝트'):'개발 · 설계 · 운영')+' — 윤준명';window.scrollTo(0,0)}
document.addEventListener('click',e=>{const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return}const f=e.target.closest('[data-filter]');if(f){main.innerHTML=portfolio(f.dataset.filter);return}if(e.target.closest('#print-resume'))window.print()});window.addEventListener('hashchange',render);render();
